const mark=(cls='brand-mark',light=false)=>`<svg class="${cls}" viewBox="0 0 32 32" aria-hidden="true"><path fill="${light?'#F2F1EC':'currentColor'}" fill-rule="evenodd" d="M5 29V3h13l9 9-8 8 9 9h-8l-9-9v9zm6-21v8h5l4-4-4-4z"/></svg>`;
const brand=(light=false)=>`<a class="brand" href="#/">${mark('brand-mark',light)}<span>Rytm</span></a>`;
const footer=()=>`<footer class="footer container"><span>© 2025 Rytm. Spokojnie o pieniądzach.</span><span><a href="#">Prywatność</a><a href="#">Kontakt</a></span></footer>`;
const header=()=>`<header class="site-header container">${brand()}<nav class="nav"><a href="#/how-it-works">Jak działa</a><a href="#/for-who">Dla kogo</a><a class="btn btn-ghost" href="#/login">Zaloguj się</a><a class="btn btn-primary" href="#/register">Zacznij</a></nav></header>`;
function landing(){return `<div class="screen"><div class="container">${header()}</div><main><section class="hero container"><div><div class="eyebrow">Spokojnie o pieniądzach</div><h1>Pieniądze uciekają w <em>rytmie.</em><br/>Rytm ten rytm pokazuje.</h1><p>Wgraj wyciąg bankowy i zobacz, które wydatki wracają zbyt często. Bez oceniania. Z jasną granicą, którą ustawiasz sam.</p><div class="hero-actions"><a class="btn btn-primary" href="#/register">Zobacz swój rytm <span>↗</span></a><a class="btn btn-ghost" href="#/how-it-works">Jak to działa?</a></div><div class="hero-note">Darmowy start · dane zostają u Ciebie</div></div><div class="hero-card"><div class="mini-top"><span>Twój miesiąc</span><span>maj 2025</span></div><div class="mini-total">3 842,60 zł</div><div class="mini-sub">wydatki rozpoznane</div><div class="bars"><i class="bar"></i><i class="bar"></i><i class="bar"></i><i class="bar"></i><i class="bar"></i><i class="bar"></i><i class="bar accent"></i><i class="bar accent"></i></div><div class="rhythm-row"><i class="rhythm-r"></i><i class="rhythm-r"></i><i class="rhythm-r"></i><i class="rhythm-r"></i><i class="rhythm-r"></i><i class="rhythm-r accent"></i><i class="rhythm-r accent"></i></div></div></section><section class="section container" id="jak-dziala"><div class="section-head"><div><div class="eyebrow">Bez arkusza</div><h2>Trzy kroki do jasności.</h2></div><span class="muted">Wystarczy jeden wieczór w miesiącu.</span></div><div class="three-cols"><article class="feature"><h3>01 — Wgraj CSV</h3><p>Wrzuć wyciąg z banku. Rytm rozpozna sprzedawców i powtarzające się kwoty.</p></article><article class="feature"><h3>02 — Ustaw granicę</h3><p>Sam decydujesz, ile kaw, dostaw lub subskrypcji mieści się w Twoim miesiącu.</p></article><article class="feature"><h3>03 — Zobacz wzorzec</h3><p>Nadwyżka trafia do widoku „spalone w tym miesiącu”. Bez wstydu, z konkretem.</p></article></div></section><section class="cta-band"><div class="container"><h2>Zobacz, gdzie cicho<br/>ucieka pieniądz.</h2><a class="btn btn-amber" href="#/register">Utwórz konto</a></div></section></main>${footer()}</div>`}
function auth(mode){const reg=mode==='register';return `<div class="auth-shell"><aside class="auth-visual">${brand(true)}<div class="auth-copy"><div class="eyebrow" style="color:#c79d62">Twój rytm</div><h1>${reg?'Zacznij widzieć więcej.':'Wróć do swojego rytmu.'}</h1><p>${reg?'Jedno konto, jeden spokojny widok Twoich wydatków.':'Twoje wzorce wydatków czekają na kolejny miesiąc.'}</p></div></aside><main class="auth-form-wrap"><form class="auth-form" onsubmit="event.preventDefault(); location.hash='#/home'"><div class="eyebrow">${reg?'Nowe konto':'Witaj ponownie'}</div><h1>${reg?'Utwórz konto':'Zaloguj się'}</h1><p>${reg?'Zacznij od adresu e-mail. Resztę ustawisz później.':'Wróć do spokojnego widoku swoich wydatków.'}</p>${reg?'<div class="field"><label for="name">Imię</label><input id="name" placeholder="np. Ola" required /></div>':''}<div class="field"><label for="email">E-mail</label><input id="email" type="email" placeholder="ty@przyklad.pl" required /></div><div class="field"><label for="password">Hasło</label><input id="password" type="password" placeholder="••••••••" required /></div>${reg?'<div class="form-row"><span>Zakładając konto akceptujesz regulamin.</span></div>':'<div class="form-row"><label><input type="checkbox"/> Zapamiętaj mnie</label><a href="#">Nie pamiętam hasła</a></div>'}<button class="btn btn-primary" type="submit">${reg?'Utwórz konto':'Zaloguj się'} <span>↗</span></button><div class="auth-footer">${reg?'Masz już konto?':'Nie masz jeszcze konta?'} <a href="${reg?'#/login':'#/register'}">${reg?'Zaloguj się':'Utwórz je'}</a></div></form></main></div>`}
function dashboard(){return `<div class="dash-shell"><header class="dash-header">${brand()}<div style="display:flex;align-items:center;gap:15px"><span class="muted" style="font-size:12px">maj 2025</span><button class="btn btn-ghost" onclick="location.hash='#/'">Wyjdź</button></div></header><div class="dash-body"><aside class="side"><div class="side-label">Widok</div><a class="active" href="#/home"><i class="side-icon"></i> Przegląd</a><a href="#"><i class="side-icon"></i> Wzorce wydatków</a><a href="#"><i class="side-icon"></i> Koszty stałe</a><div class="side-label">Dane</div><a href="#"><i class="side-icon"></i> Importy CSV</a><div class="side-bottom"><a href="#"><i class="side-icon"></i> Ustawienia</a></div></aside><main class="dash-main"><div class="dash-title"><div><div class="eyebrow">Przegląd miesiąca</div><h1>Dzień dobry, Olu.</h1><p>Oto rytm Twoich wydatków w maju.</p></div><button class="btn btn-primary" onclick="document.getElementById('file').click()">+ Wgraj CSV</button><input id="file" type="file" hidden accept=".csv" onchange="document.getElementById('fileNote').textContent='Plik gotowy do analizy'"/></div><div class="stats"><article class="stat-card accent"><div class="stat-label">Spalone w tym miesiącu</div><div class="stat-value">284,40 zł</div><div class="stat-foot">+42,20 zł względem kwietnia</div></article><article class="stat-card"><div class="stat-label">Rozpoznane wydatki</div><div class="stat-value">3 842,60 zł</div><div class="stat-foot">64 transakcje · 12 wzorców</div></article><article class="stat-card"><div class="stat-label">Koszty stałe</div><div class="stat-value">1 920 zł</div><div class="stat-foot">2 pozycje podrożały</div></article></div><div class="dash-grid"><section class="panel"><div class="panel-title"><h2>Rytm wydatków</h2><span>Ostatnie 30 dni</span></div><div class="trend"><i class="tbar" style="height:35%" data-day="1"></i><i class="tbar" style="height:52%" data-day="5"></i><i class="tbar" style="height:39%" data-day="9"></i><i class="tbar" style="height:68%" data-day="13"></i><i class="tbar" style="height:49%" data-day="17"></i><i class="tbar" style="height:80%" data-day="21"></i><i class="tbar hot" style="height:95%" data-day="25"></i><i class="tbar hot" style="height:70%" data-day="29"></i></div><div class="legend"><span><i class="dot"></i> zwykły rytm</span><span><i class="dot hot"></i> nadwyżka</span></div></section><section class="panel"><div class="panel-title"><h2>Co wraca najczęściej</h2><span>próg własny</span></div><div class="list"><div class="list-item"><div class="merchant"><span class="merchant-mark">W</span><div><div class="item-name">Wolt</div><div class="item-meta">8 razy · próg 4</div></div></div><div class="item-amount up">+84 zł</div></div><div class="list-item"><div class="merchant"><span class="merchant-mark">S</span><div><div class="item-name">Spotify</div><div class="item-meta">co miesiąc</div></div></div><div class="item-amount">24,99 zł</div></div><div class="list-item"><div class="merchant"><span class="merchant-mark">K</span><div><div class="item-name">Kawa i spółka</div><div class="item-meta">11 razy · próg 8</div></div></div><div class="item-amount up">+61 zł</div></div></div></section></div><section class="import-panel"><div class="import-copy"><span class="import-icon">↓</span><div><strong id="fileNote">Dodaj najnowszy wyciąg</strong><span>CSV z Twojego banku · dane zostają na tym urządzeniu</span></div></div><button class="btn btn-ghost" onclick="document.getElementById('file').click()">Wybierz plik</button></section></main></div></div>`}
function howItWorks(){return `<div class="screen"><div class="container">${header()}</div><main><section class="sub-hero container"><div><div class="eyebrow">Jak działa Rytm</div><h1>Najpierw wzorzec.<br/><em>Potem decyzja.</em></h1><p>Rytm porządkuje powtarzalne transakcje, żebyś raz w miesiącu widział to, co zwykle ginie w historii konta.</p><a class="btn btn-primary" href="#/register">Zacznij od swojego CSV <span>↗</span></a></div><div class="sequence-card"><div class="sequence-caption">Jedna granica, wiele powrotów</div><div class="sequence-track"><span class="seq active"></span><span class="seq active"></span><span class="seq active"></span><i></i><span class="seq over"></span><span class="seq over"></span></div><div class="sequence-labels"><span>Twój próg</span><b>Nadwyżka</b></div></div></section><section class="section container"><div class="section-head"><div><div class="eyebrow">Od pliku do obrazu</div><h2>Trzy spokojne kroki.</h2></div><span class="muted">Bez ręcznego kategoryzowania.</span></div><div class="process-grid"><article class="process-card"><span class="process-number">01</span><h3>Wgraj wyciąg</h3><p>Wybierz plik CSV z banku. Rytm czyta datę, sprzedawcę i kwotę, a potem grupuje podobne transakcje.</p><div class="process-line"></div><small>Masz kontrolę nad plikiem</small></article><article class="process-card"><span class="process-number">02</span><h3>Rozpoznaj rytm</h3><p>Stałe koszty i częste zakupy układają się w sekwencje. Widzisz, co wraca co miesiąc, tydzień lub kilka dni.</p><div class="process-line"></div><small>Wzorzec zamiast szumu</small></article><article class="process-card"><span class="process-number">03</span><h3>Ustaw granicę</h3><p>Próg jest Twój. Rytm zaznacza dopiero kolejne powtórzenia, a ich suma trafia do „spalone w tym miesiącu”.</p><div class="process-line amber"></div><small>Bez oceniania, z konkretem</small></article></div></section><section class="explain-band"><div class="container explain-grid"><div><div class="eyebrow">Co zobaczysz</div><h2>Nie jeden duży wydatek.<br/>Cały jego rytm.</h2></div><div class="explain-list"><div><b>Stałe koszty</b><span>Ta sama usługa, podobna kwota — od razu widać podwyżkę albo nową pozycję.</span></div><div><b>Częste zakupy</b><span>Ten sam sprzedawca niezależnie od kwoty — dostawy, kawa, małe decyzje.</span></div><div><b>Nadwyżka</b><span>Rytm nie mówi, co masz robić. Pokazuje miejsce, w którym możesz zdecydować.</span></div></div></div></section><section class="cta-band"><div class="container"><h2>Twój miesiąc ma<br/>swój rytm.</h2><a class="btn btn-amber" href="#/register">Zobacz go</a></div></section></main>${footer()}</div>`}
function forWho(){return `<div class="screen"><div class="container">${header()}</div><main><section class="sub-hero audience-hero container"><div><div class="eyebrow">Dla kogo jest Rytm</div><h1>Dla osoby, która chce<br/><em>wiedzieć bez liczenia.</em></h1><p>Masz dwa konta, kilka subskrypcji i zero ochoty na kolejny arkusz. Rytm daje Ci jeden spokojny moment prawdy w miesiącu.</p><div class="hero-actions"><a class="btn btn-primary" href="#/register">Sprawdź swój rytm <span>↗</span></a><a class="btn btn-ghost" href="#/how-it-works">Zobacz jak działa</a></div></div><div class="audience-note"><span class="audience-mark">R</span><p>„Nie chcę budżetu<br/>na każdy dzień.<br/><strong>Chcę widzieć wzorce.”</strong></p></div></section><section class="section container"><div class="section-head"><div><div class="eyebrow">Brzmi znajomo?</div><h2>Rytm pasuje do Twojego tempa.</h2></div></div><div class="audience-grid"><article class="audience-card"><span class="card-index">A</span><h3>Pracujesz i ogarniasz dużo</h3><p>Nie potrzebujesz kolejnego systemu do prowadzenia. Potrzebujesz krótkiego, prawdziwego obrazu.</p><a href="#/register">Raz w miesiącu <span>↗</span></a></article><article class="audience-card"><span class="card-index">B</span><h3>Masz wydatki, które wracają</h3><p>Subskrypcje, jedzenie z dowozem, kawa po drodze. Rytm pokaże częstotliwość bez moralizowania.</p><a href="#/register">Zobacz powroty <span>↗</span></a></article><article class="audience-card"><span class="card-index">C</span><h3>Chcesz ustawić własną granicę</h3><p>Nie chodzi o zakaz. Chodzi o moment, w którym nadwyżka staje się widoczna i możesz coś z nią zrobić.</p><a href="#/register">Ustaw swój próg <span>↗</span></a></article></div></section><section class="quote-band"><div class="container"><div class="eyebrow">To nie jest aplikacja do perfekcji</div><h2>To jest aplikacja do<br/><em>większej jasności.</em></h2><p>Rytm zostawia miejsce na normalne życie. Pomaga tylko zauważyć, kiedy małe decyzje zaczynają się powtarzać.</p></div></section><section class="cta-band"><div class="container"><h2>Wystarczy jeden<br/>spokojny wieczór.</h2><a class="btn btn-amber" href="#/register">Utwórz konto</a></div></section></main>${footer()}</div>`}
function render(){const p=location.hash||'#/';document.getElementById('app').innerHTML=p==='#/login'?auth('login'):p==='#/register'?auth('register'):p==='#/home'?dashboard():p==='#/how-it-works'?howItWorks():p==='#/for-who'?forWho():landing();window.scrollTo(0,0)}window.addEventListener('hashchange',render);render();
